<script setup lang="ts">
import {requestKey} from '../request-key';
import BusinessStatus from '../components/BusinessStatus.vue';
import {businessRowClass} from '../business-status';
import {ref,reactive,computed,onMounted,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {ElMessage,ElMessageBox} from 'element-plus';import {api,get,message} from '../api';import {useAuth} from '../stores/auth';import {date,ton,money,label,download} from '../fulfillment';import {openAgent} from '../agent';
const route=useRoute(),router=useRouter(),auth=useAuth(),isSettlement=computed(()=>route.path.endsWith('/settlements')),isReconcile=computed(()=>route.path.endsWith('/reconciliations')),carrier=computed(()=>auth.user?.businessEntity.type==='CARRIER'),trader=computed(()=>auth.user?.businessEntity.type==='TRADER'),canWrite=computed(()=>auth.can('billing:write'));
const filters=reactive({q:'',status:'',page:1,pageSize:20}),rows=ref<any[]>([]),total=ref(0),busy=ref(false),saving=ref(false),error=ref(''),detail=ref<any>(),drawer=ref(false),editing=ref(false),options=ref<any>({fees:[],businesses:[]}),editId=ref(''),formError=ref(''),differenceOpen=ref(false),paymentOpen=ref(false),versionOpen=ref(false),selectedVersion=ref<any>();
const statuses:Record<string,string>={DRAFT:'草稿',SENT:'未对账',CHECKING:'对账中',DISPUTED:'差异处理中',RECHECK:'待再次确认',CONFIRMED:'已确认',VOID:'已作废',PENDING:'待结算',PARTIAL:'部分结算',SETTLED:'已结算',EXCEPTION:'结算异常',OPEN:'待处理',PENDING_CONFIRMATION:'待确认',RESOLVED:'已解决',REJECTED:'对方有异议'};
const draft=reactive<any>({businessId:'',taskIds:[],periodFrom:'',periodTo:'',remark:'',reason:'',items:[]}),difference=reactive<any>({itemSequence:undefined,type:'AMOUNT',description:'',accepted:0}),payment=reactive<any>({amount:0,method:'银行转账（线下）',plannedAt:'',actualAt:'',evidenceId:'',note:'',requestKey:''});
const business=computed(()=>options.value.businesses.find((b:any)=>b.id===draft.businessId)),draftTotal=computed(()=>draft.items.reduce((s:number,i:any)=>s+Number(i.original||0)+Number(i.adjustment||0),0)),currentSettlement=computed(()=>detail.value?.settlement),canCarrier=computed(()=>carrier.value&&canWrite.value),canTrader=computed(()=>trader.value&&canWrite.value);
async function load(){busy.value=true;error.value='';try{const response=await get(isSettlement.value?'/billing/settlements':'/billing/bills',{...filters,status:filters.status||undefined});rows.value=response.items;total.value=response.total;if(route.query.id)await show(String(route.query.id),false);}catch(e){error.value=message(e);}finally{busy.value=false;}}
async function show(id:string,update=true){try{detail.value=await get('/billing/bills/'+id);drawer.value=true;if(update)router.replace({query:{id}});}catch(e){error.value=message(e);}}
async function begin(){try{options.value=await get('/billing/options');editId.value='';Object.assign(draft,{businessId:'',taskIds:[],periodFrom:new Date(Date.now()-30*86400000).toISOString(),periodTo:new Date().toISOString(),remark:'',reason:'',items:[]});formError.value='';editing.value=true;}catch(e){error.value=message(e);}}
function selectBusiness(){draft.taskIds=[];draft.items=[];}
function addItem(){draft.items.push({feeCode:options.value.fees[0]?.code||'',taskId:draft.taskIds[0]||'',quantity:1,unit:'吨',price:0,original:0,adjustment:0,occurredAt:new Date().toISOString(),basis:''});}
function priceChanged(i:any){i.original=Math.round(Number(i.quantity)*Number(i.price)*100)/100;}
async function edit(){try{options.value=await get('/billing/options');if(!options.value.businesses.some((b:any)=>b.id===detail.value.businessId))options.value.businesses.push({id:detail.value.businessId,businessNo:detail.value.reference.logisticsNo,package:{businessNo:detail.value.reference.contractNo,snapshot:detail.value.reference.snapshot,totalCents:detail.value.reference.contractAmountCents},tasks:detail.value.reference.tasks});editId.value=detail.value.id;Object.assign(draft,{businessId:detail.value.businessId,taskIds:detail.value.tasks.map((t:any)=>t.taskId),periodFrom:detail.value.periodFrom,periodTo:detail.value.periodTo,remark:detail.value.remark,reason:'',items:detail.value.items.map((i:any)=>({feeCode:i.feeCode,taskId:i.taskId||undefined,sourceId:i.sourceId||undefined,quantity:i.quantityMillis/1000,unit:i.unit,price:i.unitPriceCents/100,original:i.originalCents/100,adjustment:i.adjustmentCents/100,occurredAt:i.occurredAt,basis:i.basis}))});formError.value='';editing.value=true;}catch(e){error.value=message(e);}}
async function save(){formError.value='';if(!draft.businessId||!draft.taskIds.length||!draft.items.length){formError.value='请选择已完成业务、结算任务并添加费用明细';return;}saving.value=true;try{const data={businessId:draft.businessId,taskIds:draft.taskIds,periodFrom:draft.periodFrom,periodTo:draft.periodTo,remark:draft.remark,reason:draft.reason,items:draft.items.map((i:any)=>({feeCode:i.feeCode,taskId:i.taskId||undefined,sourceId:i.sourceId||undefined,quantityMillis:Math.round(i.quantity*1000),unit:i.unit,unitPriceCents:Math.round(i.price*100),originalCents:Math.round(i.original*100),adjustmentCents:Math.round(i.adjustment*100),occurredAt:i.occurredAt,basis:i.basis})),...(editId.value?{version:detail.value.version}:{})};const response=editId.value?await api.put('/billing/bills/'+editId.value,data):await api.post('/billing/bills',data);editing.value=false;ElMessage.success(editId.value&&detail.value.status==='DISPUTED'?'已生成新版本并重新提交':'账单已保存');await show(response.data.data.id);await load();}catch(e){formError.value=message(e);}finally{saving.value=false;}}
async function action(action:string){try{await ElMessageBox.confirm(({submit:'提交后贸易企业与平台可查看本版本账单。',confirm:'确认当前版本费用无误，将形成唯一结算依据。',withdraw:'撤回后可继续编辑草稿。',void:'作废账单将释放任务结算范围。',check:'开始核对当前账单费用。'} as any)[action],'确认业务操作',{confirmButtonText:'确认',cancelButtonText:'取消'});saving.value=true;await api.post(`/billing/bills/${detail.value.id}/${action}`,{version:detail.value.version});await show(detail.value.id,false);await load();ElMessage.success('操作已记录');}catch(e){if(e!=='cancel'&&e!=='close')error.value=message(e);}finally{saving.value=false;}}
function beginDifference(){Object.assign(difference,{itemSequence:undefined,type:'AMOUNT',description:'',accepted:detail.value.totalCents/100});formError.value='';differenceOpen.value=true;}
async function sendDifference(){saving.value=true;formError.value='';try{await api.post('/billing/bills/'+detail.value.id+'/differences',{version:detail.value.version,itemSequence:difference.itemSequence||undefined,type:difference.type,description:difference.description,acceptedCents:Math.round(difference.accepted*100)});differenceOpen.value=false;await show(detail.value.id,false);await load();ElMessage.success('差异已提交给承运方');}catch(e){formError.value=message(e);}finally{saving.value=false;}}
async function upload(event:Event){const f=(event.target as HTMLInputElement).files?.[0];if(!f)return;saving.value=true;try{const form=new FormData();form.append('file',f);const e=(await api.post('/billing/bills/'+detail.value.id+'/evidence',form)).data.data;payment.evidenceId=e.id;await show(detail.value.id,false);ElMessage.success('凭证已保存');}catch(e){formError.value=message(e);}finally{saving.value=false;(event.target as HTMLInputElement).value='';}}
function beginPayment(){Object.assign(payment,{amount:(currentSettlement.value.confirmedCents-currentSettlement.value.settledCents)/100,method:'银行转账（线下）',plannedAt:new Date().toISOString(),actualAt:new Date().toISOString(),evidenceId:'',note:'',requestKey:requestKey()});formError.value='';paymentOpen.value=true;}
async function recordPayment(){saving.value=true;try{await api.post('/billing/settlements/'+currentSettlement.value.id+'/records',{version:currentSettlement.value.version,requestKey:payment.requestKey,amountCents:Math.round(payment.amount*100),method:payment.method,plannedAt:payment.plannedAt,actualAt:payment.actualAt,evidenceId:payment.evidenceId,note:payment.note});paymentOpen.value=false;await show(detail.value.id,false);await load();ElMessage.success('已登记，等待另一方确认');}catch(e){formError.value=message(e);}finally{saving.value=false;}}
async function confirmPayment(record:any,accepted:boolean){try{let reason='确认无误';if(!accepted){const input=await ElMessageBox.prompt('说明金额、日期或凭证的差异','登记结算异常',{inputValidator:v=>v?.trim().length>=2||'请填写异常说明'});reason=input.value;}else await ElMessageBox.confirm('核对凭证与线下实际结算结果后确认。','确认结算结果');saving.value=true;await api.post(`/billing/settlements/${currentSettlement.value.id}/records/${record.id}/confirm`,{version:currentSettlement.value.version,accepted,reason});await show(detail.value.id,false);await load();ElMessage.success(accepted?'结算结果已确认':'结算异常已记录');}catch(e){if(e!=='cancel'&&e!=='close')error.value=message(e);}finally{saving.value=false;}}
async function exportBill(){try{const data=await get('/billing/bills/'+detail.value.id+'/archive');download(JSON.stringify(data,null,2),detail.value.businessNo+'-归档.json','application/json');}catch(e){error.value=message(e);}}
function sourceEvidence(item:any){const f=detail.value?.reference.fees?.find((f:any)=>f.id===item.sourceId);if(!f?.evidenceId)return null;const task=detail.value.reference.tasks.find((t:any)=>t.id===f.taskId),stage=detail.value.reference.stages.find((s:any)=>s.id===f.stageId);return task?.evidence?.find((e:any)=>e.id===f.evidenceId)?{...task.evidence.find((e:any)=>e.id===f.evidenceId),driver:true}:stage?.attachments?.find((e:any)=>e.id===f.evidenceId);}
async function downloadSource(item:any){const f=sourceEvidence(item);if(!f)return;try{const response=await api.get((f.driver?'/fulfillment/evidence/':'/intermodal/attachments/')+f.id,{responseType:'blob'});download(response.data,f.name,f.mime);}catch(e){error.value=message(e);}}
async function file(e:any){try{const response=await api.get('/billing/evidence/'+e.id,{responseType:'blob'});download(response.data,e.name,e.mime);}catch(e){error.value=message(e);}}
watch(()=>route.path,()=>{filters.page=1;filters.status='';drawer.value=false;load();});watch(()=>route.query.id,id=>{if(id&&id!==detail.value?.id)show(String(id),false);});onMounted(load);
</script>
<template><div class="finance-page"><el-alert v-if="error" :title="error" type="error" :closable="false"/><div class="finance-filters"><el-input v-model="filters.q" aria-label="搜索账单" placeholder="账单 / 运单 / 合同编号" clearable @keyup.enter="filters.page=1;load()"/><el-select v-model="filters.status" aria-label="账单状态" placeholder="全部状态" clearable><el-option v-for="s in (isSettlement?['PENDING','PARTIAL','SETTLED','EXCEPTION']:['DRAFT','SENT','CHECKING','DISPUTED','RECHECK','CONFIRMED','VOID'])" :key="s" :value="s" :label="statuses[s]"/></el-select><div class="filter-actions"><el-button @click="filters.page=1;load()">查询</el-button></div></div>
<div class="finance-table"><el-table :row-class-name="businessRowClass" :data="rows" v-loading="busy" @row-click="(row:any)=>show(isSettlement?row.billId:row.id)"><el-table-column :label="isSettlement?'结算单编号':'账单编号'" min-width="210"><template #default="{row}"><strong class="business-number">{{row.businessNo}}</strong></template></el-table-column><el-table-column label="关联合同与运单" min-width="210"><template #default="{row}"><strong>{{(row.bill||row).reference.contractNo}}</strong><small>{{(row.bill||row).reference.waybillNo||(row.bill||row).reference.logisticsNo}}</small></template></el-table-column><el-table-column label="商业双方" min-width="180"><template #default="{row}">{{(row.bill||row).reference.snapshot.trader?.name}}<small>{{(row.bill||row).reference.snapshot.carrier?.name}}</small></template></el-table-column><el-table-column :label="isSettlement?'应结金额':'账单金额'" width="140" align="right"><template #default="{row}"><strong>{{money(isSettlement?row.confirmedCents:row.totalCents)}}</strong><small v-if="!isSettlement">{{ton(row.quantityKg)}} · {{row.items.length}} 项费用</small></template></el-table-column><el-table-column v-if="isSettlement" label="已结 / 未结" width="160" align="right"><template #default="{row}">{{money(row.settledCents)}}<small>余额 {{money(row.confirmedCents-row.settledCents)}}</small></template></el-table-column><el-table-column label="状态" width="140"><template #default="{row}"><BusinessStatus :status="row.status" :label="statuses[row.status]"/><small v-if="!isSettlement">当前版本 V{{row.version}}{{row.archivedAt?' · 已归档':''}}</small></template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button link type="primary" @click.stop="show(isSettlement?row.billId:row.id)">查看详情</el-button></template></el-table-column><template #empty><el-empty :description="isSettlement?'尚无已确认对账的结算记录':'暂无账单，联运业务完成后自动生成'"/></template></el-table><div class="finance-pagination"><el-pagination v-model:current-page="filters.page" :page-size="filters.pageSize" :total="total" layout="total, prev, pager, next" @current-change="load"/></div></div>
<el-drawer v-model="drawer" :title="detail?.businessNo||'账单详情'" size="920px" @closed="router.replace({query:{}})"><template v-if="detail"><div class="bill-summary"><div><small>账单总额</small><strong>{{money(detail.totalCents)}}</strong><BusinessStatus :status="detail.status" :label="statuses[detail.status]+' · V'+detail.version"/></div><div><small>实际签收参考</small><strong>{{ton(detail.quantityKg)}}</strong><span>同一货物经过不同区段，不累加为唯一货量</span></div><div><small>合同约定参考</small><strong>{{money(detail.reference.contractAmountCents)}}</strong><span>{{detail.reference.contractNo}}</span></div></div><div class="bill-links"><router-link :to="'/contracts/archives?id='+detail.packageId">合同档案 →</router-link><router-link :to="'/services?businessId='+detail.businessId">联运服务 →</router-link><el-button link type="primary" @click="drawer=false;openAgent({contextType:'bill',contextId:detail.id})">智能核对参考</el-button><el-button link @click="exportBill">导出账单与归档资料</el-button></div><p class="finance-note">周期 {{date(detail.periodFrom)}} — {{date(detail.periodTo)}} · {{detail.reference.snapshot.trader?.name}} → {{detail.reference.snapshot.carrier?.name}}</p><p class="finance-note">结算约定：{{detail.reference.terms?.settlement||'见合同约定'}} · {{detail.remark}}</p><h3>费用明细</h3><el-table :data="detail.items"><el-table-column prop="sequence" label="序号" width="65"/><el-table-column label="费用项目 / 来源" min-width="150"><template #default="{row}">{{row.feeName}}<small>{{({CONTRACT:'合同费用',DRIVER:'司机回传',OTHER:'其他费用',TASK:'任务费用'} as any)[row.sourceType]}}</small></template></el-table-column><el-table-column label="数量 / 单价" min-width="155"><template #default="{row}">{{row.unit==='吨'?ton(row.quantityMillis):row.quantityMillis/1000+' '+row.unit}}<small>{{money(row.unitPriceCents)}} / {{row.unit}}</small></template></el-table-column><el-table-column label="原始 / 调整" width="150" align="right"><template #default="{row}">{{money(row.originalCents)}}<small>调整 {{money(row.adjustmentCents)}}</small></template></el-table-column><el-table-column label="最终金额" width="130" align="right"><template #default="{row}"><strong>{{money(row.finalCents)}}</strong></template></el-table-column><el-table-column label="执行与费用依据" min-width="200"><template #default="{row}">{{label(row.mode)}} · {{row.resource}}<small>{{row.basis}}</small><el-button v-if="sourceEvidence(row)" link type="primary" @click="downloadSource(row)">查看费用凭证</el-button><router-link v-if="row.taskId" :to="'/tracking/journeys?taskId='+row.taskId">查看区段执行 →</router-link></template></el-table-column></el-table>
<h3>实际执行依据</h3><el-table :data="detail.reference.tasks"><el-table-column prop="businessNo" label="任务编号" min-width="210"/><el-table-column label="区段" width="120"><template #default="{row}">第 {{row.segment}} 程 · {{label(row.mode)}}</template></el-table-column><el-table-column label="装载 / 签收数量" min-width="180"><template #default="{row}">{{ton(row.loadedKg)}} / {{ton(row.unloadedKg)}}</template></el-table-column><el-table-column label="执行结果" width="100"><template #default="{row}">{{label(row.status)}}</template></el-table-column></el-table>
<div class="bill-action-bar"><el-button v-if="canCarrier&&['DRAFT','DISPUTED'].includes(detail.status)" @click="edit">{{detail.status==='DISPUTED'?'处理差异并调整':'编辑草稿'}}</el-button><el-button v-if="canCarrier&&detail.status==='DRAFT'" type="primary" :loading="saving" @click="action('submit')">提交对账</el-button><el-button v-if="canCarrier&&!detail.serviceCompletionKey&&detail.status==='SENT'&&!detail.differences.length" @click="action('withdraw')">撤回账单</el-button><el-button v-if="canCarrier&&!detail.serviceCompletionKey&&['DRAFT','SENT'].includes(detail.status)" @click="action('void')">作废</el-button><el-button v-if="canTrader&&['SENT','RECHECK'].includes(detail.status)" @click="action('check')">开始核对</el-button><el-button v-if="canTrader&&['SENT','CHECKING','RECHECK'].includes(detail.status)" @click="beginDifference">发起差异</el-button><el-button v-if="canTrader&&['SENT','CHECKING','RECHECK'].includes(detail.status)" type="primary" :loading="saving" @click="action('confirm')">确认对账</el-button></div>
<h3>差异与协商</h3><el-empty v-if="!detail.differences.length" description="暂无费用差异" :image-size="45"/><div v-for="d in detail.differences" :key="d.id" class="difference-record"><header><strong>{{d.itemSequence?'第 '+d.itemSequence+' 项':'整张账单'}} · V{{d.billVersion}}</strong><BusinessStatus :status="d.status" :label="statuses[d.status]"/></header><p>{{d.description}}</p><small>账单 {{money(d.billedCents)}} / 认可 {{money(d.acceptedCents)}} · {{date(d.createdAt)}}</small><p v-if="d.resolution">承运方处理：{{d.resolution}} · {{date(d.handledAt)}}</p></div>
<template v-if="currentSettlement"><h3>结算记录 · {{currentSettlement.businessNo}}</h3><div class="settlement-summary"><div><small>确认金额</small><strong>{{money(currentSettlement.confirmedCents)}}</strong></div><div><small>已确认结算</small><strong>{{money(currentSettlement.settledCents)}}</strong></div><div><small>未结金额</small><strong>{{money(currentSettlement.confirmedCents-currentSettlement.settledCents)}}</strong></div><BusinessStatus :status="currentSettlement.status" :label="statuses[currentSettlement.status]"/></div><p class="finance-note">凭证为双方线下结算留痕，确认记录与账单一起归档。</p><el-button v-if="canWrite&&(carrier||trader)&&currentSettlement.status!=='SETTLED'&&!currentSettlement.records.some((r:any)=>r.status==='PENDING')" type="primary" @click="beginPayment">登记线下结算结果</el-button><div v-for="r in currentSettlement.records" :key="r.id" class="difference-record"><header><strong>{{money(r.amountCents)}} · {{r.method}}</strong><BusinessStatus :status="r.status" :label="statuses[r.status]||'待另一方确认'"/></header><p>实际结算 {{date(r.actualAt)}} · 登记 {{date(r.createdAt)}}</p><p>{{r.note}} {{r.response}}</p><template v-if="canWrite&&r.status==='PENDING'&&r.registeredEntityId!==auth.user?.businessEntityId"><el-button type="primary" :loading="saving" @click="confirmPayment(r,true)">确认结算结果</el-button><el-button @click="confirmPayment(r,false)">存在结算差异</el-button></template></div><el-alert v-if="detail.archivedAt" :title="'费用闭环已归档 · '+date(detail.archivedAt)" type="success" :closable="false"/></template>
<h3>费用与结算凭证</h3><div class="finance-evidence"><el-button v-for="e in detail.evidence" :key="e.id" link type="primary" @click="file(e)">{{e.name}} ↓</el-button><label v-if="canWrite&&!detail.archivedAt&&detail.status!=='VOID'">添加凭证<input aria-label="添加账单凭证" type="file" accept=".pdf,.png,.jpg,.jpeg" :disabled="saving" @change="upload"/></label></div><h3>不可覆盖的历史版本</h3><el-table :data="detail.versions"><el-table-column label="版本" width="85"><template #default="{row}">V{{row.number}}</template></el-table-column><el-table-column label="金额" width="140"><template #default="{row}">{{money(row.snapshot.totalCents)}}</template></el-table-column><el-table-column prop="reason" label="变更原因"/><el-table-column label="时间" width="180"><template #default="{row}">{{date(row.createdAt)}}</template></el-table-column><el-table-column width="95"><template #default="{row}"><el-button link @click="selectedVersion=row;versionOpen=true">查看快照</el-button></template></el-table-column></el-table><h3>操作留痕</h3><div v-for="l in detail.logs" :key="l.id" class="finance-log"><strong>{{l.action}}</strong><span>{{l.userName}} · {{date(l.createdAt)}}</span></div></template></el-drawer>
<el-dialog v-model="editing" title="调整账单" width="1080px" :close-on-click-modal="false"><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><el-form label-position="top"><div class="finance-form-grid"><el-form-item label="可结算运输业务"><el-select v-model="draft.businessId" aria-label="可结算运输业务" :disabled="!!editId" filterable @change="selectBusiness"><el-option v-for="b in options.businesses" :key="b.id" :value="b.id" :label="b.businessNo+' · '+b.package.businessNo"/></el-select></el-form-item><el-form-item label="结算任务范围"><el-select v-model="draft.taskIds" aria-label="结算任务范围" multiple :disabled="!!editId"><el-option v-for="t in business?.tasks||[]" :key="t.id" :value="t.id" :label="t.businessNo+' · 第 '+t.segment+' 程 · 签收 '+ton(t.unloadedKg)"/></el-select></el-form-item><el-form-item label="周期开始"><el-date-picker v-model="draft.periodFrom" aria-label="周期开始" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss.SSSZ"/></el-form-item><el-form-item label="周期结束"><el-date-picker v-model="draft.periodTo" aria-label="周期结束" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss.SSSZ"/></el-form-item></div><p v-if="business" class="finance-note">合同参考 {{money(business.package.totalCents)}} · {{business.package.snapshot.origin}} → {{business.package.snapshot.destination}}</p><div class="bill-edit-items"><article v-for="(i,index) in draft.items" :key="index"><header><strong>费用 {{index+1}}</strong><el-button link type="danger" @click="draft.items.splice(index,1)">移除</el-button></header><div class="fee-grid"><el-form-item label="费用项目"><el-select v-model="i.feeCode" :aria-label="'费用项目 '+(index+1)"><el-option v-for="f in options.fees" :key="f.code" :value="f.code" :label="f.label"/></el-select></el-form-item><el-form-item label="关联任务"><el-select v-model="i.taskId" :aria-label="'关联任务 '+(index+1)"><el-option v-for="t in (business?.tasks||[]).filter((t:any)=>draft.taskIds.includes(t.id))" :key="t.id" :value="t.id" :label="t.businessNo"/></el-select></el-form-item><el-form-item label="数量"><el-input-number v-model="i.quantity" :aria-label="'费用数量 '+(index+1)" :min="i.unit==='吨'?0.1:0.001" :precision="i.unit==='吨'?1:3" :step="i.unit==='吨'?0.1:0.001" @change="priceChanged(i)"/></el-form-item><el-form-item label="单位"><el-select v-model="i.unit"><el-option v-for="u in ['吨','车','箱','次','天']" :key="u" :value="u"/></el-select></el-form-item><el-form-item label="单价（元）"><el-input-number v-model="i.price" :aria-label="'费用单价 '+(index+1)" :min="0" :precision="2" @change="priceChanged(i)"/></el-form-item><el-form-item label="原始金额（元）"><el-input-number v-model="i.original" :aria-label="'原始金额 '+(index+1)" :min="0" :precision="2"/></el-form-item><el-form-item label="调整金额（元）"><el-input-number v-model="i.adjustment" :aria-label="'调整金额 '+(index+1)" :precision="2"/></el-form-item><el-form-item label="发生时间"><el-date-picker v-model="i.occurredAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss.SSSZ"/></el-form-item></div><el-form-item label="费用依据 / 说明"><el-input v-model="i.basis" :aria-label="'费用依据 '+(index+1)" type="textarea" :rows="2" maxlength="2000"/></el-form-item><p class="fee-final">最终金额 ¥{{(Number(i.original||0)+Number(i.adjustment||0)).toFixed(2)}}</p></article></div><el-button :disabled="!draft.taskIds.length" @click="addItem">添加费用明细</el-button><el-form-item label="备注"><el-input v-model="draft.remark" aria-label="账单备注" maxlength="2000"/></el-form-item><el-form-item v-if="detail?.status==='DISPUTED'&&editId" label="差异处理意见（生成新版本并重新提交）"><el-input v-model="draft.reason" aria-label="差异处理意见" type="textarea" :rows="3"/></el-form-item></el-form><template #footer><strong class="draft-total">合计 ¥{{draftTotal.toFixed(2)}}</strong><el-button @click="editing=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">{{detail?.status==='DISPUTED'&&editId?'生成新版本并重新提交':'保存草稿'}}</el-button></template></el-dialog>
<el-dialog v-model="differenceOpen" title="发起费用差异" width="580px"><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><el-form label-position="top"><el-form-item label="差异范围"><el-select v-model="difference.itemSequence" aria-label="差异范围" clearable placeholder="整张账单"><el-option v-for="i in detail?.items" :key="i.sequence" :value="i.sequence" :label="'第 '+i.sequence+' 项 · '+i.feeName"/></el-select></el-form-item><el-form-item label="差异类型"><el-select v-model="difference.type"><el-option v-for="[v,l] in [['AMOUNT','金额差异'],['QUANTITY','数量差异'],['PRICE','单价差异'],['FEE','费用项目'],['DUPLICATE','重复费用'],['EVIDENCE','依据不足'],['OTHER','其他']]" :key="v" :value="v" :label="l"/></el-select></el-form-item><el-form-item label="认可金额（元）"><el-input-number v-model="difference.accepted" aria-label="认可金额" :min="0" :precision="2"/></el-form-item><el-form-item label="差异说明"><el-input v-model="difference.description" aria-label="差异说明" type="textarea" :rows="4"/></el-form-item></el-form><template #footer><el-button @click="differenceOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="sendDifference">提交差异</el-button></template></el-dialog>
<el-dialog v-model="paymentOpen" title="登记线下结算结果" width="680px"><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><el-form label-position="top"><div class="finance-form-grid"><el-form-item label="本次结算金额（元）"><el-input-number v-model="payment.amount" aria-label="本次结算金额" :min="0.01" :precision="2"/></el-form-item><el-form-item label="结算方式"><el-input v-model="payment.method" aria-label="结算方式"/></el-form-item><el-form-item label="计划结算日期"><el-date-picker v-model="payment.plannedAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss.SSSZ"/></el-form-item><el-form-item label="实际结算日期"><el-date-picker v-model="payment.actualAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss.SSSZ"/></el-form-item></div><el-form-item label="本方结算凭证"><el-select v-model="payment.evidenceId" aria-label="结算凭证"><el-option v-for="e in detail?.evidence.filter((e:any)=>e.entityId===auth.user?.businessEntityId)" :key="e.id" :value="e.id" :label="e.name"/></el-select><label class="payment-upload">上传新的凭证<input aria-label="上传结算凭证" type="file" accept=".pdf,.png,.jpg,.jpeg" :disabled="saving" @change="upload"/></label></el-form-item><el-form-item label="备注"><el-input v-model="payment.note" aria-label="结算备注" type="textarea" :rows="3"/></el-form-item></el-form><template #footer><el-button @click="paymentOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="recordPayment">登记并等待对方确认</el-button></template></el-dialog>
<el-dialog v-model="versionOpen" :title="'历史版本 V'+selectedVersion?.number" width="760px"><template v-if="selectedVersion"><p>{{selectedVersion.reason}} · {{date(selectedVersion.createdAt)}}</p><h3>{{money(selectedVersion.snapshot.totalCents)}} · {{statuses[selectedVersion.snapshot.status]}}</h3><el-table :data="selectedVersion.snapshot.items"><el-table-column prop="feeName" label="费用项目"/><el-table-column prop="basis" label="依据"/><el-table-column label="最终金额"><template #default="{row}">{{money(row.finalCents)}}</template></el-table-column></el-table></template></el-dialog>
</div></template>
<style scoped>.finance-filters{display:flex;gap:12px;align-items:center;flex-wrap:wrap;background:var(--surface);padding:16px;border:1px solid var(--border);border-radius:8px;margin:20px 0}.finance-filters .el-input{width:320px}.finance-filters .el-select{width:180px}.finance-table{background:var(--surface);border:1px solid var(--border);border-radius:8px;overflow:hidden}.finance-pagination{display:flex;justify-content:flex-end;padding:20px}.finance-page :deep(.el-table small){display:block;font-size:11px;color:var(--text-secondary);margin-top:6px;white-space:normal}.finance-page :deep(.el-table a){font-size:11px;color:var(--info)}.bill-summary{display:grid;grid-template-columns:1.2fr 1fr 1fr;gap:20px;border-bottom:1px solid var(--border);padding-bottom:24px}.bill-summary>div,.settlement-summary>div{display:flex;flex-direction:column;gap:10px}.bill-summary small,.settlement-summary small{font-size:11px;color:var(--text-secondary)}.bill-summary strong{font-size:23px;font-variant-numeric:tabular-nums}.bill-summary span{font-size:10px;color:var(--text-secondary);line-height:1.8}.bill-summary .el-tag{align-self:flex-start}.bill-links{display:flex;align-items:center;gap:20px;flex-wrap:wrap;margin:20px 0;color:var(--info);font-size:12px}.finance-note{font-size:12px;line-height:1.9;color:var(--text-secondary);margin:12px 0}.finance-page :deep(.el-drawer h3){font-size:14px;margin:28px 0 16px}.bill-action-bar{display:flex;gap:12px;flex-wrap:wrap;margin:20px 0}.bill-action-bar .el-button{margin:0}.difference-record{border:1px solid var(--border);border-radius:6px;padding:16px;margin-bottom:12px;font-size:12px;line-height:1.9}.difference-record header{display:flex;justify-content:space-between;gap:12px;align-items:center}.difference-record p{margin:8px 0}.difference-record small{color:var(--text-secondary)}.settlement-summary{display:flex;align-items:center;gap:40px;padding:20px;background:var(--page-bg);border-radius:8px}.settlement-summary strong{font-size:18px}.finance-evidence{display:flex;flex-direction:column;align-items:flex-start;gap:12px}.finance-evidence .el-button{margin:0}.finance-evidence label,.payment-upload{display:flex;gap:12px;flex-direction:column;font-size:12px;color:var(--text-secondary)}.payment-upload{margin-top:12px}.finance-log{display:flex;gap:20px;justify-content:space-between;font-size:11px;padding:12px 0;border-bottom:1px solid var(--divider)}.finance-log span{color:var(--text-secondary)}.finance-form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 20px}.finance-form-grid :deep(.el-date-editor){width:100%}.bill-edit-items article{border:1px solid var(--border);border-radius:6px;padding:16px;margin:20px 0}.bill-edit-items header{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;font-size:13px}.fee-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:0 12px}.fee-grid :deep(.el-input-number),.fee-grid :deep(.el-date-editor){width:100%}.fee-final{text-align:right;font-size:14px;font-weight:600}.draft-total{margin-right:24px;font-size:16px}@media(max-width:700px){.finance-filters .el-input{width:100%}.bill-summary{grid-template-columns:1fr}.bill-summary strong{font-size:20px}.finance-form-grid,.fee-grid{grid-template-columns:1fr}.settlement-summary{gap:16px;flex-wrap:wrap}.finance-log{flex-direction:column;gap:6px}.draft-total{display:block;margin:0 0 16px}}</style>
